<?php
require __DIR__ . '/bootstrap.php';require_login();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{supabase('PATCH','admin_settings?id=eq.true',['payment_initiation_threshold'=>(float)$_POST['threshold'],'currency'=>$_POST['currency'],'auto_approve_users'=>isset($_POST['auto_approve'])]);$message='Settings saved.';}catch(Throwable $e){$error=$e->getMessage();}}
try{$rows=supabase('GET','admin_settings?select=*&id=eq.true');$settings=$rows[0]??['payment_initiation_threshold'=>5000,'currency'=>'NGN','auto_approve_users'=>false];}catch(Throwable $e){$settings=['payment_initiation_threshold'=>5000,'currency'=>'NGN','auto_approve_users'=>false];$error=$e->getMessage();}
$content='<div class="mb-4"><h2 class="h4">Platform settings</h2><p class="text-muted">Configure payment and approval rules.</p></div>'.($message?'<div class="alert alert-success">'.e($message).'</div>':'').($error?'<div class="alert alert-danger">'.e($error).'</div>':'').'<div class="card rounded-4 p-4" style="max-width:650px"><form method="post"><label class="form-label">Payment threshold<input class="form-control" name="threshold" type="number" min="0" step="0.01" value="'.e($settings['payment_initiation_threshold']).'"></label><label class="form-label">Currency<select class="form-select" name="currency"><option '.($settings['currency']==='NGN'?'selected':'').'>NGN</option><option '.($settings['currency']==='USD'?'selected':'').'>USD</option></select></label><div class="form-check mb-3"><input class="form-check-input" name="auto_approve" type="checkbox" '.(!empty($settings['auto_approve_users'])?'checked':'').'><label class="form-check-label">Automatically approve registrations</label></div><button class="btn btn-primary">Save settings</button></form></div>';$title='Settings';page($title,$content);
